const b=$input.first().json.body ?? {};
if(b.agentKey!=='ancfz'||!['quotation','invoice'].includes(b.documentType)) throw new Error('Invalid ANCFZ document type');
const esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function money(v){if(typeof v!=='number'||!Number.isFinite(v)||v<0)throw new Error('Invalid amount');return v.toFixed(2);}
if(!Array.isArray(b.lines)||b.lines.length<1||b.lines.length>40)throw new Error('Invalid lines');
const currency=String(b.currency??'');
if(!/^[A-Z]{3}$/.test(currency))throw new Error('Invalid currency');
const rows=b.lines.map(line=>'<tr><td>'+esc(String(line.label??'').slice(0,200))+'</td><td style="text-align:right">'+esc(currency)+' '+money(line.amount)+'</td></tr>').join('');
const total=b.lines.reduce((sum,line)=>sum+Number(line.amount),0);
if(Math.abs(total-Number(b.total))>0.001)throw new Error('Total mismatch');
if(b.documentType==='invoice' && b.paymentVerified!==true)throw new Error('Invoice requires verified test payment');
const heading=b.documentType==='invoice'?'TEST PAYMENT INVOICE':'QUOTATION';
const note=b.documentType==='invoice'?'Sandbox payment confirmed. Not proof of real funds.':'This quotation is subject to ANCFZ approval and documented conditions.';
const html='<!doctype html><html><head><meta charset="UTF-8"><style>body{font:15px Arial,sans-serif;margin:36px;color:#172333}h1{color:#155db3}table{border-collapse:collapse;width:100%;margin-top:25px}th,td{border-bottom:1px solid #ccc;padding:10px;text-align:left}.muted{color:#536073;font-size:12px}</style></head><body><h1>ANCFZ</h1><h2>'+heading+'</h2><p>Document: '+esc(String(b.documentNumber??'').slice(0,100))+'</p><p>Customer: '+esc(String(b.customerName??'').slice(0,200))+'</p><table><tr><th>Description</th><th style="text-align:right">Amount</th></tr>'+rows+'</table><h3 style="text-align:right">Total: '+esc(currency)+' '+money(total)+'</h3><p class="muted">'+note+'</p></body></html>';
return [{json:{documentType:b.documentType,documentNumber:String(b.documentNumber??''),ticketId:String(b.ticketId??'')},binary:{html:{data:Buffer.from(html,'utf8').toString('base64'),mimeType:'text/html',fileName:'index.html'}}}];

const pdf=await this.helpers.getBinaryDataBuffer(0,'data');
if(pdf.length<100 || pdf.length>5242880 || pdf.subarray(0,5).toString()!=='%PDF-')throw new Error('Invalid PDF bytes');
const original=$('Prepare Escaped HTML').first().json;
return [{json:{status:'generated',documentType:original.documentType,documentNumber:original.documentNumber,ticketId:original.ticketId,mimeType:'application/pdf',pdfBase64:pdf.toString('base64')}}];
